import{_ as t,o as a,c as n,b6 as r}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"Introducción al Proyecto","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/guide/introduction.md","filePath":"es-es/guide/introduction.md"}'),d={name:"es-es/guide/introduction.md"};function i(l,e,o,s,c,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="introduccion-al-proyecto" tabindex="-1">Introducción al Proyecto <a class="header-anchor" href="#introduccion-al-proyecto" aria-label="Permalink to “Introducción al Proyecto”">​</a></h1><p>2025 es considerado por muchos como el año inaugural de la programación con IA. Cada vez más personas comienzan a usar IA para escribir código, pero a menudo los resultados se quedan en el nivel de juguetes: no saben cómo organizar el flujo de desarrollo con Vibe Coding, no saben qué herramientas elegir, y mucho menos cuáles son los pasos clave entre el prototipo y el despliegue en producción.</p><p>Adoptamos una <strong>ruta práctica de tres etapas, progresiva</strong>: la etapa de iniciación permite a los novatos familiarizarse rápidamente con la programación con IA a través de juegos pequeños; la primera etapa domina el flujo de trabajo de Vibe Coding y completa un prototipo de aplicación web; la segunda etapa aprende desarrollo fullstack y despliegue en producción; la tercera etapa construye aplicaciones complejas multiplataforma.</p><p>Cada etapa está acompañada de proyectos prácticos completos, que te permiten avanzar de juguete a producto en desafíos reales, y finalmente adquirir la capacidad de <strong>convertir cualquier idea en una aplicación funcional</strong>.</p><p>Creemos que, dominando Vibe Coding junto con un entrenamiento sistemático, una sola persona puede convertirse en un <strong>desarrollador integral que combina desarrollo frontend y backend, integración de capacidades de IA y diseño de productos</strong>.</p><p>Este proyecto está dirigido principalmente a tres tipos de aprendices:</p><ul><li><strong>Novatos (personas sin formación técnica / perfiles de producto y operaciones)</strong>: ayuda a quienes no tienen antecedentes técnicos y a los aprendices principiantes a comprender los conceptos clave y completar su primera herramienta de IA o prototipo de producto.</li><li><strong>Desarrolladores junior e intermedios (estudiantes y desarrolladores con cierta base)</strong>: dominar sistemáticamente vibe coding y el desarrollo de aplicaciones nativas de IA.</li><li><strong>Desarrolladores senior (empresas y startups, desarrolladores de código abierto e independientes)</strong>: apoyar a equipos e individuos para construir, validar e iterar rápidamente aplicaciones nativas de IA.</li></ul><h2 id="📖-navegacion-de-contenido" tabindex="-1">📖 Navegación de Contenido <a class="header-anchor" href="#📖-navegacion-de-contenido" aria-label="Permalink to “📖 Navegación de Contenido”">​</a></h2><h3 id="apendice-general" tabindex="-1">Apéndice General <a class="header-anchor" href="#apendice-general" aria-label="Permalink to “Apéndice General”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/es-es/appendix/8-artificial-intelligence/ai-capability-dictionary.html">Diccionario de capacidades de IA: conceptos centrales, términos y escenarios comunes de IA</a></p><h3 id="etapa-cero-jardin-de-infancia" tabindex="-1">Etapa Cero: Jardín de Infancia <a class="header-anchor" href="#etapa-cero-jardin-de-infancia" aria-label="Permalink to “Etapa Cero: Jardín de Infancia”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido clave</th><th style="text-align:left;">Estado</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/learning-map/">Introducción: Mapa de aprendizaje</a></td><td style="text-align:left;">Visión general de la ruta de aprendizaje completa</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/ai-capabilities-through-games/">Introducción: En la era de la IA, saber hablar es saber programar</a></td><td style="text-align:left;">Experimentar inicialmente las capacidades de la programación con IA a través de casos como el juego Snake</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="etapa-uno-product-manager-de-ia" tabindex="-1">Etapa Uno: Product Manager de IA <a class="header-anchor" href="#etapa-uno-product-manager-de-ia" aria-label="Permalink to “Etapa Uno: Product Manager de IA”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido clave</th><th style="text-align:left;">Estado</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/introduction-to-ai-ide/">Nivel 2: Conociendo las herramientas AI IDE</a></td><td style="text-align:left;">Aprender a usar IDE, dominar la estructura de la interfaz y las formas eficientes de usar prompts</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/building-prototype/">Nivel 3: Construyendo un prototipo</a></td><td style="text-align:left;">Ciclo completo desde el análisis de producto hasta la implementación de un prototipo multipágina</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/integrating-ai-capabilities/">Nivel 4: Añadiendo capacidades de IA al prototipo</a></td><td style="text-align:left;">Comprender y completar la integración de API de capacidades de IA comunes (texto, imagen, video)</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/complete-project-practice/">Nivel 5: Práctica de proyecto completo</a></td><td style="text-align:left;">Simular escenarios reales, recibir retroalimentación de usuarios, iterar y completar la presentación del proyecto (incluye proyecto final)</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="apendices" tabindex="-1">Apéndices <a class="header-anchor" href="#apendices" aria-label="Permalink to “Apéndices”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido clave</th><th style="text-align:left;">Estado</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/appendix-a-product-thinking/">Apéndice A: Pensamiento de producto</a></td><td style="text-align:left;">Marco de pensamiento de producto desde la evaluación de ideas hasta la descomposición de requisitos y MVP</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/appendix-b-common-errors/">Apéndice B: Errores comunes y soluciones</a></td><td style="text-align:left;">Errores comunes en vibe coding y métodos de solución</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/appendix-idea-sources/">Apéndice: De dónde sacar ideas</a></td><td style="text-align:left;">Encontrar direcciones específicas a partir de aplicaciones de referencia, tendencias y listas de VC</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/appendix-double-diamond/">Apéndice: Modelo Double Diamond</a></td><td style="text-align:left;">Comprender el ritmo completo de definir primero el problema y luego desarrollar la solución</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/appendix-jobs-to-be-done/">Apéndice: Jobs to Be Done</a></td><td style="text-align:left;">Usar el método JTBD para comprender lo que el usuario realmente quiere lograr</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-1/appendix-mom-test/">Apéndice: Método de entrevistas The Mom Test</a></td><td style="text-align:left;">Método de investigación para validar necesidades a través de entrevistas con usuarios</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="etapa-dos-desarrollador-junior-e-intermedio" tabindex="-1">Etapa Dos: Desarrollador Junior e Intermedio <a class="header-anchor" href="#etapa-dos-desarrollador-junior-e-intermedio" aria-label="Permalink to “Etapa Dos: Desarrollador Junior e Intermedio”">​</a></h3><h4 id="parte-frontend" tabindex="-1">Parte Frontend <a class="header-anchor" href="#parte-frontend" aria-label="Permalink to “Parte Frontend”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido clave</th><th style="text-align:left;">Estado</th></tr></thead><tbody><tr><td style="text-align:left;">Uso de Lovart para producir materiales</td><td style="text-align:left;">Aprender a usar Lovart para generar por lotes materiales visuales como personajes y escenarios, proporcionando una base de materiales para el diseño UI y el desarrollo frontend</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Introducción a Figma y MasterGo</td><td style="text-align:left;">Usar herramientas de diseño para organizar la arquitectura de información y la estructura de páginas, sentando las bases para la implementación frontend</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Construir la primera aplicación moderna - Diseño UI</td><td style="text-align:left;">Completar una interfaz basada en componentes a partir del diseño, realizando el primer enlace de diseño a código</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Diseñar páginas y botones con referencia a especificaciones de diseño UI</td><td style="text-align:left;">Aprender a organizar la estructura de páginas y la jerarquía de botones con especificaciones de diseño convencionales, y usar IA para generar esquemas de diseño</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-2/frontend/hogwarts-portraits/">Construyendo retratos de Hogwarts juntos</a></td><td style="text-align:left;">De 0 a 1, crear una aplicación frontend integrando capacidades de IA, uniendo diseño y desarrollo</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="parte-de-desarrollo-backend" tabindex="-1">Parte de Desarrollo Backend <a class="header-anchor" href="#parte-de-desarrollo-backend" aria-label="Permalink to “Parte de Desarrollo Backend”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido clave</th><th style="text-align:left;">Estado</th></tr></thead><tbody><tr><td style="text-align:left;">Qué es una API</td><td style="text-align:left;">Comprender las interfaces HTTP y el modelo petición-respuesta, preparándose para la integración backend y la depuración conjunta</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-2/backend/database-supabase/">De la base de datos a Supabase</a></td><td style="text-align:left;">Implementar bases de datos y APIs en Supabase, conectando modelos de datos con páginas frontend</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Modelos grandes asistiendo en la redacción de código de interfaz y documentación de interfaz</td><td style="text-align:left;">Usar modelos grandes para ayudar a generar interfaces, documentación de base de datos y código, logrando un backend legible y testeable</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Flujo de trabajo Git y despliegue en Zeabur</td><td style="text-align:left;">Gestionar código en un flujo de trabajo Git, y desplegar la aplicación en Zeabur para ponerla en línea</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Herramientas modernas de desarrollo CLI</td><td style="text-align:left;">Usar herramientas de programación AI tipo CLI para acelerar el desarrollo y la depuración, formando un flujo de trabajo de ingeniería personal</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Cómo integrar sistemas de pago como Stripe</td><td style="text-align:left;">Integrar sistemas de pago, completando el enlace de cobro y el flujo básico de liquidación</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Construir la primera aplicación moderna - Aplicación fullstack</td><td style="text-align:left;">Integrar frontend, backend y módulo de pago para completar una aplicación web fullstack que pueda ponerse en línea</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Biblioteca de componentes frontend moderna + Práctica con Trae</td><td style="text-align:left;">Usar una biblioteca de componentes frontend moderna y Trae para completar independientemente un producto con login, registro y soporte de pago</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="apendice-de-capacidades-de-ia" tabindex="-1">Apéndice de Capacidades de IA <a class="header-anchor" href="#apendice-de-capacidades-de-ia" aria-label="Permalink to “Apéndice de Capacidades de IA”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido clave</th><th style="text-align:left;">Estado</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/es-es/stage-2/ai-capabilities/dify-knowledge-base/">Introducción a Dify e integración de base de conocimientos</a></td><td style="text-align:left;">Usar Dify Workflow y RAG básico para construir un producto tipo herramienta, preparando el terreno para futuras actualizaciones de aplicaciones</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Aprender a consultar el diccionario de IA e integrar APIs multimodales</td><td style="text-align:left;">Aprender a encontrar modelos y APIs adecuados, e integrar capacidades multimodales como texto e imagen en el producto</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="etapa-tres-desarrollador-senior" tabindex="-1">Etapa Tres: Desarrollador Senior <a class="header-anchor" href="#etapa-tres-desarrollador-senior" aria-label="Permalink to “Etapa Tres: Desarrollador Senior”">​</a></h3>',24)])])}const u=t(d,[["render",i]]);export{y as __pageData,u as default};
